(573414, 58784, 16301, '<td valign="top">Very creative, I like the sad/smiley face idea. You put a new and intresting idea to this technique. The DOF and detail is great, and the lighting is perfect. Good luck...</td>', 'Very creative, I like the sad/smiley face idea. You put a new and intresting idea to this technique. The DOF and detail is great, and the lighting is perfect. Good luck...', '2004-02-09 12:41:00.000000', NULL, 1),
(573421, 59269, 327, '<td valign="top">Really nicely done. Love the colors, light control and title. All works.</td>', 'Really nicely done. Love the colors, light control and title. All works.', '2004-02-09 12:46:06.000000', NULL, 1),
(573422, 58640, 327, '<td valign="top">Nothing wrong with this shot at all. I just find it a bit unoriginal, it''s been done so often. I don''t mark down for that, just tossing it out. The shot is good.</td>', 'Nothing wrong with this shot at all. I just find it a bit unoriginal, it''s been done so often. I don''t mark down for that, just tossing it out. The shot is good.', '2004-02-09 12:47:39.000000', NULL, 1),
