(573932, 59273, 8624, '<td valign="top">interesting subject and cool colors. I think this might have been more effective if the tubes in the background had more space between them.</td>', 'interesting subject and cool colors. I think this might have been more effective if the tubes in the background had more space between them.', '2004-02-09 21:36:34.000000', NULL, 1),
(573935, 59269, 2752, '<td valign="top">good choice of rod and reel ...excellent dof..well composed...I personally used that combination of rod and reel for 50 years...with great results.Getting back to the photo..no overblown highlights..shine without glare.  .  great angles..well done.<br/>(8)</td>', 'good choice of rod and reel ...excellent dof..well composed...I personally used that combination of rod and reel for 50 years...with great results.Getting back to the photo..no overblown highlights..shine without glare.  .  great angles..well done.(8)', '2004-02-09 21:40:01.000000', NULL, 1),
(573939, 59136, 12733, '<td valign="top">Good shallow DOF, but as I look at the picture, I feel it would be stronger without the out-of-focus jade plants. The single sharp plant against the out-of-focus leaves gives a great 3-D effect and still meets the requirements of the challenge.</td>', 'Good shallow DOF, but as I look at the picture, I feel it would be stronger without the out-of-focus jade plants. The single sharp plant against the out-of-focus leaves gives a great 3-D effect and still meets the requirements of the challenge.', '2004-02-09 21:45:31.000000', NULL, 1),
(573940, 59127, 14606, '<td valign="top">very cool.  that''s about as narrow DOF as you can get.</td>', 'very cool.  that''s about as narrow DOF as you can get.', '2004-02-09 21:46:00.000000', NULL, 1),
(573942, 58650, 8624, '<td valign="top">cool portrait of Pete. He has a very expressive face. I like the B+W treatment. I think though, that you could have cropped it in a more interesting way, removing a little more from his back and shoulders. I like the background space in front of him and that would be accentuated more if he was more off center. great job! 9</td>', 'cool portrait of Pete. He has a very expressive face. I like the B+W treatment. I think though, that you could have cropped it in a more interesting way, removing a little more from his back and shoulders. I like the background space in front of him and that would be accentuated more if he was more off center. great job! 9', '2004-02-09 21:46:17.000000', NULL, 1),
(573943, 59292, 12733, '<td valign="top">Nice color contrast between the plant and the out-of-focus background. The unsharp bud in the front detracts some, but still a nce shot.</td>', 'Nice color contrast between the plant and the out-of-focus background. The unsharp bud in the front detracts some, but still a nce shot.', '2004-02-09 21:47:16.000000', NULL, 1),
(573945, 59300, 8624, '<td valign="top">very creative composition. nice interpretation of the challenge.</td>', 'very creative composition. nice interpretation of the challenge.', '2004-02-09 21:48:02.000000', NULL, 1),
(573946, 59290, 12733, '<td valign="top">Good use of shallow DOF to make the one broken lance stand out from the rest.</td>', 'Good use of shallow DOF to make the one broken lance stand out from the rest.', '2004-02-09 21:48:33.000000', NULL, 1),
(573949, 58491, 8624, '<td valign="top">nice use of a Slinky! great lighting and colors.</td>', 'nice use of a Slinky! great lighting and colors.', '2004-02-09 21:49:06.000000', NULL, 1),
(573953, 59214, 12733, '<td valign="top">You have one beautiful chess set there. Great use of DOF to highlight the triumphant pawn, and nice lighting overall.</td>', 'You have one beautiful chess set there. Great use of DOF to highlight the triumphant pawn, and nice lighting overall.', '2004-02-09 21:50:34.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(573956, 58784, 8624, '<td valign="top">this technique is getting to be cliche, but it is well suited to this assignment and you have done a nice job with the focus, shallow DOF and colors.</td>', 'this technique is getting to be cliche, but it is well suited to this assignment and you have done a nice job with the focus, shallow DOF and colors.', '2004-02-09 21:53:12.000000', NULL, 1),
(573958, 58491, 12733, '<td valign="top">I like the colors and metallic textures, but this could be a case of "less is more." It''s hard to find a way into the picture, there''s too much going on at once.</td>', 'I like the colors and metallic textures, but this could be a case of "less is more." It''s hard to find a way into the picture, there''s too much going on at once.', '2004-02-09 21:53:59.000000', NULL, 1),
(573959, 59187, 12253, '<td valign="top">Nice concept, good tones and perspective.  But my perception is that she should have been looking in the direction of the hands.  Also, there seems to be a lack of sharpness in the "in focus" areas.</td>', 'Nice concept, good tones and perspective.  But my perception is that she should have been looking in the direction of the hands.  Also, there seems to be a lack of sharpness in the "in focus" areas.', '2004-02-09 21:54:20.000000', NULL, 1),
(573964, 58894, 12253, '<td valign="top">Not sure why you didn''t put these "behind" each other more, to show more drop off in focus.  As it is, there''s little dynamic effect of DOF here.</td>', 'Not sure why you didn''t put these "behind" each other more, to show more drop off in focus.  As it is, there''s little dynamic effect of DOF here.', '2004-02-09 21:55:43.000000', NULL, 1),
(573966, 59303, 12733, '<td valign="top">I don''t know what they are, but they make an interesting pattern.</td>', 'I don''t know what they are, but they make an interesting pattern.', '2004-02-09 21:55:48.000000', NULL, 1),
(573967, 59300, 12253, '<td valign="top">Good idea, for some reason, perhaps postprocessing, the grape looks very flat!  might be too much USM?  Or it might be the lighting you used.</td>', 'Good idea, for some reason, perhaps postprocessing, the grape looks very flat!  might be too much USM?  Or it might be the lighting you used.', '2004-02-09 21:57:18.000000', NULL, 1),
(573969, 59021, 8624, '<td valign="top">good lighting for a live show shot. I think the hair on the right is a major distraction though.</td>', 'good lighting for a live show shot. I think the hair on the right is a major distraction though.', '2004-02-09 21:58:21.000000', NULL, 1),
(573971, 59217, 12253, '<td valign="top">A nice 3D effect, but I think the effect s overdone.  Perhaps the beak sticking out would have worked, but the feet don''t, as they are dangling in space.  It''s actually hard to see the connection between the foreground bird and the tree, so he doesn''t appear to be part of the picture.</td>', 'A nice 3D effect, but I think the effect s overdone.  Perhaps the beak sticking out would have worked, but the feet don''t, as they are dangling in space.  It''s actually hard to see the connection between the foreground bird and the tree, so he doesn''t appear to be part of the picture.', '2004-02-09 21:59:41.000000', NULL, 1),
(573974, 58672, 12253, '<td valign="top">Looks like my backyard.  Very good scene, good composition.  DOF works well here, though it is minimally applied.</td>', 'Looks like my backyard.  Very good scene, good composition.  DOF works well here, though it is minimally applied.', '2004-02-09 22:00:39.000000', NULL, 1),
(573976, 58899, 8624, '<td valign="top">absolutely gorgeous lanscape. I don''t know that I would characterize this as shallow DOF, but it''s a great image. the metal loops on the right are a little distracting, though.</td>', 'absolutely gorgeous lanscape. I don''t know that I would characterize this as shallow DOF, but it''s a great image. the metal loops on the right are a little distracting, though.', '2004-02-09 22:01:14.000000', NULL, 1),
(573985, 58941, 2223, '<td valign="top">That is a very neat trick! Love it! 10</td>', 'That is a very neat trick! Love it! 10', '2004-02-09 22:05:48.000000', NULL, 1),
(573991, 59259, 8624, '<td valign="top">good choice of subjects. the lighting is uneven though  with the faces very overexposed.</td>', 'good choice of subjects. the lighting is uneven though  with the faces very overexposed.', '2004-02-09 22:08:54.000000', NULL, 1),
(573999, 58924, 8624, '<td valign="top">ood idea, but I wish the 8 ball itself was more in focus.</td>', 'ood idea, but I wish the 8 ball itself was more in focus.', '2004-02-09 22:12:14.000000', NULL, 1),
(574004, 59160, 2223, '<td valign="top">Just amazing!</td>', 'Just amazing!', '2004-02-09 22:14:21.000000', NULL, 1),
(574018, 58992, 6600, '<td valign="top">Stunning, nice example for the challenge.  Very detailed and nicely composed.  I like the contrasting dark/light areas.  Nicely done.</td>', 'Stunning, nice example for the challenge.  Very detailed and nicely composed.  I like the contrasting dark/light areas.  Nicely done.', '2004-02-09 22:23:44.000000', NULL, 1),
