(574410, 59127, 6999, '<td valign="top">Exytaordinarily un-sharp, when seen so close. I like the graphical element to this image - the contrasting weight of the curves and the straight line in the background. DOF is obviously correct, perhaps even <i>too</i> extreme, or at least maybe too sudden - the fringe of field seems very abrupt to me.</td>', 'Exytaordinarily un-sharp, when seen so close. I like the graphical element to this image - the contrasting weight of the curves and the straight line in the background. DOF is obviously correct, perhaps even too extreme, or at least maybe too sudden - the fringe of field seems very abrupt to me.', '2004-02-10 10:50:49.000000', NULL, 1),
(574411, 58927, 179, '<td valign="top">Has to be one of my favs. "A" for originality, awesome colors. 10. Very nicely done. Good luck!</td>', 'Has to be one of my favs. "A" for originality, awesome colors. 10. Very nicely done. Good luck!', '2004-02-10 10:51:12.000000', NULL, 1),
