(578398, 58941, 16912, '<td valign="top">worried about how much of this came out of the camera</td>', 'worried about how much of this came out of the camera', '2004-02-12 19:21:01.000000', NULL, 1),
(578410, 59205, 16912, '<td valign="top">Love it, and the way the viewer is drawn to the 8 makes me realise how much you thought about the setup. Does the clever positioning of the eight make me move from my intital seven or take it to nine?</td>', 'Love it, and the way the viewer is drawn to the 8 makes me realise how much you thought about the setup. Does the clever positioning of the eight make me move from my intital seven or take it to nine?', '2004-02-12 19:35:37.000000', NULL, 1),
(578426, 58615, 8860, '<td valign="top">There''s not a lot to hold the attention here. Colours are good and it meets the challenge, but it''s just not very appealing to me. It also looks like the Photoshop lighting effect filter has been used, since the arc lies flatly over the undulating pages.</td>', 'There''s not a lot to hold the attention here. Colours are good and it meets the challenge, but it''s just not very appealing to me. It also looks like the Photoshop lighting effect filter has been used, since the arc lies flatly over the undulating pages.', '2004-02-12 19:44:19.000000', NULL, 1),
(578427, 59258, 6667, '<td valign="top">Very nice approach to the challenge.  My only comment is that the macro focus takes the picture too quickly from sharp to faded.  Still. . . nicely done. BOL</td>', 'Very nice approach to the challenge.  My only comment is that the macro focus takes the picture too quickly from sharp to faded.  Still. . . nicely done. BOL', '2004-02-12 19:45:13.000000', NULL, 1),
(578428, 59225, 8860, '<td valign="top">Good, clean, simple shot. Meets challenge, but isn''t particularly special beyond those criteria.</td>', 'Good, clean, simple shot. Meets challenge, but isn''t particularly special beyond those criteria.', '2004-02-12 19:45:20.000000', NULL, 1),
(578433, 59273, 8860, '<td valign="top">Intriguing subject. I feel though that I''d prefer to see just the one - very close up. The distant objects just don''t seem to have purpose. Great colour.</td>', 'Intriguing subject. I feel though that I''d prefer to see just the one - very close up. The distant objects just don''t seem to have purpose. Great colour.', '2004-02-12 19:46:48.000000', NULL, 1),
(578437, 59043, 6667, '<td valign="top">Certainly met the challenge. Color tones are too closely related. BOL</td>', 'Certainly met the challenge. Color tones are too closely related. BOL', '2004-02-12 19:50:01.000000', NULL, 1),
(578439, 59061, 8860, '<td valign="top">Meets challenge and is a lovely subject. Composition is a little too low and the colours in the background do not gel very well with the butterfly''s wings. Crisp, clean shot.</td>', 'Meets challenge and is a lovely subject. Composition is a little too low and the colours in the background do not gel very well with the butterfly''s wings. Crisp, clean shot.', '2004-02-12 19:50:49.000000', NULL, 1),
(578440, 59308, 6667, '<td valign="top">Love the soft tones.  nicely done. BOL</td>', 'Love the soft tones.  nicely done. BOL', '2004-02-12 19:51:11.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(578444, 59288, 8860, '<td valign="top">Doesn''t meet the challenge. [1]<br/> <br/> <br/>Just kidding. Very sumptuous shot. Like the red spot editing, although I get the urge to find more meaning in the shot than I believe there is, which prevents it from having that x-factor for me.</td>', 'Doesn''t meet the challenge. [1]  Just kidding. Very sumptuous shot. Like the red spot editing, although I get the urge to find more meaning in the shot than I believe there is, which prevents it from having that x-factor for me.', '2004-02-12 19:55:08.000000', NULL, 1),
(578448, 59157, 8860, '<td valign="top">Lovely little shot. Could this have been titled ''Crocus Focus''? Yup - you''re right, I''ll get my coat...</td>', 'Lovely little shot. Could this have been titled ''Crocus Focus''? Yup - you''re right, I''ll get my coat...', '2004-02-12 19:57:11.000000', NULL, 1),
(578452, 58925, 8860, '<td valign="top">Doesn''t meet the challenge at all. It''s rubbish. [1]<br/> <br/> <br/> <br/>Oh - alright it does then. Well here it is - shallow DOF. Good perspective and colour - but there is not a great deal of interest in the shot besides it meeting the brief and I find myself hunting for some meaning or pun.</td>', 'Doesn''t meet the challenge at all. It''s rubbish. [1]   Oh - alright it does then. Well here it is - shallow DOF. Good perspective and colour - but there is not a great deal of interest in the shot besides it meeting the brief and I find myself hunting for some meaning or pun.', '2004-02-12 20:01:46.000000', NULL, 1),
(578454, 58781, 6667, '<td valign="top">From the looks of the background, you cropped this into an interesting shot.  Nicely done. BOL</td>', 'From the looks of the background, you cropped this into an interesting shot.  Nicely done. BOL', '2004-02-12 20:04:05.000000', NULL, 1),
(578455, 58661, 8860, '<td valign="top">Despite meeting the challenge successfully here I do find that the subject is jst not interesting enough. Ideally, shallow DOF should draw your eye to a feature of interest or something of importance. Here, I don''t think it would matter if this was shallow or deep DOF.<br/> <br/>Lighting is quite muted with an overall yellowy colour cast.</td>', 'Despite meeting the challenge successfully here I do find that the subject is jst not interesting enough. Ideally, shallow DOF should draw your eye to a feature of interest or something of importance. Here, I don''t think it would matter if this was shallow or deep DOF. Lighting is quite muted with an overall yellowy colour cast.', '2004-02-12 20:04:28.000000', NULL, 1),
(578462, 59306, 8860, '<td valign="top">You''ve very nearly got it all in focus here! Cute little car, but neither is the shot incredibly on-brief, or engaging - although you have some nice detail. <br/> <br/>Personally I think this shot would be improved with longer DOF since the shallowness does nothing to draw your eye to anything in particular and actually serves to frustratingly blur parts that you want to see.</td>', 'You''ve very nearly got it all in focus here! Cute little car, but neither is the shot incredibly on-brief, or engaging - although you have some nice detail.  Personally I think this shot would be improved with longer DOF since the shallowness does nothing to draw your eye to anything in particular and actually serves to frustratingly blur parts that you want to see.', '2004-02-12 20:08:17.000000', NULL, 1),
(578463, 59196, 8860, '<td valign="top">Sensitively balanced shot - lovely colours, lighting and a delicate subject. It''s a pretty picture, but perhaps that''s all - despite your title.</td>', 'Sensitively balanced shot - lovely colours, lighting and a delicate subject. It''s a pretty picture, but perhaps that''s all - despite your title.', '2004-02-12 20:10:13.000000', NULL, 1),
(578466, 58640, 8860, '<td valign="top">The glasses shots have been done many times and i will confess to being quite bored with them. However, given the challenge brief this does have purpose and it''s well photographed. <br/> <br/>One flaw though is the composition which is too centred for my taste. I feel it would have been better balanced to show more of the left side and reduce to dominant shape on the right. Dark areas are little too burned too.</td>', 'The glasses shots have been done many times and i will confess to being quite bored with them. However, given the challenge brief this does have purpose and it''s well photographed.  One flaw though is the composition which is too centred for my taste. I feel it would have been better balanced to show more of the left side and reduce to dominant shape on the right. Dark areas are little too burned too.', '2004-02-12 20:13:32.000000', NULL, 1),
(578468, 58898, 8860, '<td valign="top">Crisp shot, good colour, but the composition is too central and it lacks real interest aside from meeting the challenge.</td>', 'Crisp shot, good colour, but the composition is too central and it lacks real interest aside from meeting the challenge.', '2004-02-12 20:14:54.000000', NULL, 1),
(578470, 59030, 8860, '<td valign="top">Good little study which has merit beyond the challenge. I like the tones and lighting as well as the hues you have chosen.</td>', 'Good little study which has merit beyond the challenge. I like the tones and lighting as well as the hues you have chosen.', '2004-02-12 20:17:23.000000', NULL, 1),
(578473, 59110, 8860, '<td valign="top">Does the job for me. Nice pic, colours, focus, lighting, etc., but perhaps beyond the challenge brief there is not much of interest here. <br/> <br/>BTW, I''ve got the same ''egg-cups'' too. ;)</td>', 'Does the job for me. Nice pic, colours, focus, lighting, etc., but perhaps beyond the challenge brief there is not much of interest here.  BTW, I''ve got the same ''egg-cups'' too. ;)', '2004-02-12 20:19:30.000000', NULL, 1),
(578476, 58892, 8860, '<td valign="top">This is  agood capture, although a little soft and suffering some lack of appealing colour. Unfortunately, the squirrel appears to have a soft halo where it looks like the b/ground may have been selected for blurring.</td>', 'This is  agood capture, although a little soft and suffering some lack of appealing colour. Unfortunately, the squirrel appears to have a soft halo where it looks like the b/ground may have been selected for blurring.', '2004-02-12 20:22:53.000000', NULL, 1),
(578477, 58829, 6667, '<td valign="top">And perectly expressed it is!  Allllmost.  BOL</td>', 'And perectly expressed it is!  Allllmost.  BOL', '2004-02-12 20:25:29.000000', NULL, 1),
(578494, 58892, 16230, '<td valign="top">This is a wonderful shot. It would have been better with a different background.</td>', 'This is a wonderful shot. It would have been better with a different background.', '2004-02-12 20:48:31.000000', NULL, 1),
(578497, 59157, 16230, '<td valign="top">This is a beautiful photo!</td>', 'This is a beautiful photo!', '2004-02-12 20:51:55.000000', NULL, 1),
(578498, 58554, 1717, '<td valign="top">great texture and detail.</td>', 'great texture and detail.', '2004-02-12 20:53:30.000000', NULL, 1),
(578499, 59248, 16230, '<td valign="top">Very nice. I like it.</td>', 'Very nice. I like it.', '2004-02-12 20:54:57.000000', NULL, 1),
(578500, 59259, 1717, '<td valign="top">these are so cute and you have a nice composition and focus.  the lighting seems just a bit too hot, though.</td>', 'these are so cute and you have a nice composition and focus.  the lighting seems just a bit too hot, though.', '2004-02-12 20:55:42.000000', NULL, 1),
(578506, 58473, 1717, '<td valign="top">beautiful detail and tone.  i love the composition.  makes me feel how delicate and precarious life can be.</td>', 'beautiful detail and tone.  i love the composition.  makes me feel how delicate and precarious life can be.', '2004-02-12 21:00:12.000000', NULL, 1),
(578510, 59260, 13772, '<td valign="top">I like the picture! I just think that the colors are too close to each other to really get a good feel for DOF and I think there is too much negative space with the green. Maybe something in the back ground ( too the left side) would help give a better feel. Like the ice hand or something. Just a thought.</td>', 'I like the picture! I just think that the colors are too close to each other to really get a good feel for DOF and I think there is too much negative space with the green. Maybe something in the back ground ( too the left side) would help give a better feel. Like the ice hand or something. Just a thought.', '2004-02-12 21:03:25.000000', NULL, 1),
(578512, 59132, 1717, '<td valign="top">beautiful color...great DOF</td>', 'beautiful color...great DOF', '2004-02-12 21:05:18.000000', NULL, 1),
(578520, 58950, 1717, '<td valign="top">very intriguing image.  wonderful capture of the onlooker''s facial expressions.  raises all sorts of questions in my mind...i like that about this pic.  great work!</td>', 'very intriguing image.  wonderful capture of the onlooker''s facial expressions.  raises all sorts of questions in my mind...i like that about this pic.  great work!', '2004-02-12 21:10:51.000000', NULL, 1),
(578540, 59013, 1717, '<td valign="top">what a sweet photo!  definitely one that i would keep working on.  looks to me like you''ve clipped the image a little too much when trying to edit out the background.  a little more work and this would be great.</td>', 'what a sweet photo!  definitely one that i would keep working on.  looks to me like you''ve clipped the image a little too much when trying to edit out the background.  a little more work and this would be great.', '2004-02-12 21:29:12.000000', NULL, 1),
(578550, 58950, 5007, '<td valign="top">Hope you will tell us the story behind this photo</td>', 'Hope you will tell us the story behind this photo', '2004-02-12 21:39:30.000000', NULL, 1),
(578555, 58794, 6624, '<td valign="top">love these red pandas - nice satisfaction of the challenge</td>', 'love these red pandas - nice satisfaction of the challenge', '2004-02-12 21:42:06.000000', NULL, 1),
