(578558, 59211, 15407, '<td valign="top">Is this a filtered ''soft focus'' ? Parts of the picture them seem to be at the same depth are not in the same sharp focus?  What lens &amp; focal length did you use?</td>', 'Is this a filtered ''soft focus'' ? Parts of the picture them seem to be at the same depth are not in the same sharp focus?  What lens & focal length did you use?', '2004-02-12 21:43:29.000000', NULL, 1),
(578573, 58332, 15407, '<td valign="top">I like it. Perhaps a very slight varation on the composure of the shot may have made even better. (Ha easy for me to say)  The reflection in the mirror (you taking the picture?)  the heading on the compas with a shallow depthy of field works well for me.</td>', 'I like it. Perhaps a very slight varation on the composure of the shot may have made even better. (Ha easy for me to say)  The reflection in the mirror (you taking the picture?)  the heading on the compas with a shallow depthy of field works well for me.', '2004-02-12 21:51:15.000000', NULL, 1),
(578589, 59196, 10330, '<td valign="top">Wow!  Absolutely incredible, photo editing, all around.  Way to go!!<br/></td>', 'Wow!  Absolutely incredible, photo editing, all around.  Way to go!!', '2004-02-12 22:03:48.000000', NULL, 1),
(578591, 59269, 13772, '<td valign="top">Really creative and great composition! This should be a ribbon winner.</td>', 'Really creative and great composition! This should be a ribbon winner.', '2004-02-12 22:06:39.000000', NULL, 1),
