(578604, 59157, 326, '<td valign="top">BEAUTIFUL..... I can''t wait until spring :)</td>', 'BEAUTIFUL..... I can''t wait until spring :)', '2004-02-12 22:17:40.000000', NULL, 1),
(578607, 58794, 326, '<td valign="top">I love all the colors in this shot! Good job.</td>', 'I love all the colors in this shot! Good job.', '2004-02-12 22:20:21.000000', NULL, 1),
(578609, 59288, 326, '<td valign="top">A perfect picture of something very strange :) NuTs? I like this.</td>', 'A perfect picture of something very strange :) NuTs? I like this.', '2004-02-12 22:23:21.000000', NULL, 1),
(578612, 58602, 326, '<td valign="top">Great colors! Good job.</td>', 'Great colors! Good job.', '2004-02-12 22:26:47.000000', NULL, 1),
(578617, 59022, 13772, '<td valign="top">Beautiful subject and such a big smile. Makes me want to smile! Nice capture of shallow dept.</td>', 'Beautiful subject and such a big smile. Makes me want to smile! Nice capture of shallow dept.', '2004-02-12 22:31:49.000000', NULL, 1),
(578621, 58820, 326, '<td valign="top">Awesome shot! looks like blown glass</td>', 'Awesome shot! looks like blown glass', '2004-02-12 22:38:24.000000', NULL, 1),
(578624, 59127, 326, '<td valign="top">Simply awesome</td>', 'Simply awesome', '2004-02-12 22:40:20.000000', NULL, 1),
(578626, 58892, 326, '<td valign="top">Nice Shot</td>', 'Nice Shot', '2004-02-12 22:44:54.000000', NULL, 1),
(578638, 59249, 6870, '<td valign="top">I really enjoy the ultra-narrow focus here. The very blurry pencils still retain their diagonal lines, which keep the drama and excitement.</td>', 'I really enjoy the ultra-narrow focus here. The very blurry pencils still retain their diagonal lines, which keep the drama and excitement.', '2004-02-12 23:02:00.000000', NULL, 1),
(578639, 59006, 6870, '<td valign="top">Fun background, or underground, or whatever. The quilt was a great idea. Lots of fun colors and lines and shapes here. now if only I knew what these were . . .</td>', 'Fun background, or underground, or whatever. The quilt was a great idea. Lots of fun colors and lines and shapes here. now if only I knew what these were . . .', '2004-02-12 23:02:49.000000', NULL, 1),
(578640, 59160, 326, '<td valign="top">Perfect!</td>', 'Perfect!', '2004-02-12 23:03:21.000000', NULL, 1),
(578641, 58960, 6870, '<td valign="top">The shallow depth of field here creates a sense that there is much much more to study and discover. 8</td>', 'The shallow depth of field here creates a sense that there is much much more to study and discover. 8', '2004-02-12 23:03:24.000000', NULL, 1),
(578642, 58992, 6870, '<td valign="top">Fun, intimate image! I do wish the tongue were also in focus, but I love the lighting, and the cropping is unique and interesting.</td>', 'Fun, intimate image! I do wish the tongue were also in focus, but I love the lighting, and the cropping is unique and interesting.', '2004-02-12 23:04:05.000000', NULL, 1),
(578643, 59211, 6870, '<td valign="top">She''s a cutie! Your depth of field here is displaced, perhaps by soft focus? Anyway, I really like her expression, those pretty blue eyes, and the lovely, Swedish teeth. Nice composition, nice photo!</td>', 'She''s a cutie! Your depth of field here is displaced, perhaps by soft focus? Anyway, I really like her expression, those pretty blue eyes, and the lovely, Swedish teeth. Nice composition, nice photo!', '2004-02-12 23:05:22.000000', NULL, 1),
(578644, 59276, 6870, '<td valign="top">The dof here helps indicate that the world of this diner goes on and on. Nice nostalgic feel.</td>', 'The dof here helps indicate that the world of this diner goes on and on. Nice nostalgic feel.', '2004-02-12 23:06:01.000000', NULL, 1),
(578646, 59200, 15407, '<td valign="top">From the fruit back the picture works very well for me. The foreground including the container for the ''fruit tree'' looks to be blurred after the image was captured. Am I wrong?</td>', 'From the fruit back the picture works very well for me. The foreground including the container for the ''fruit tree'' looks to be blurred after the image was captured. Am I wrong?', '2004-02-12 23:06:42.000000', NULL, 1),
(578648, 59200, 6870, '<td valign="top">Interesting composition. I really enjoy the balance of this still life. The dof hints at more interesting items that go beyond the frame. I''m not sure what those items might be--your clues are perhaps not defined enough for that--but this is nevertheless an interesting and engaging photo!</td>', 'Interesting composition. I really enjoy the balance of this still life. The dof hints at more interesting items that go beyond the frame. I''m not sure what those items might be--your clues are perhaps not defined enough for that--but this is nevertheless an interesting and engaging photo!', '2004-02-12 23:07:43.000000', NULL, 1),
(578650, 59205, 6870, '<td valign="top">Very cool. I don''t know what these are, but the tilt and the dof indicate that they are something worth exploring with the eye and mind.</td>', 'Very cool. I don''t know what these are, but the tilt and the dof indicate that they are something worth exploring with the eye and mind.', '2004-02-12 23:08:25.000000', NULL, 1),
(578652, 58899, 15407, '<td valign="top">I don''t see a ''shallow'' depth of field.</td>', 'I don''t see a ''shallow'' depth of field.', '2004-02-12 23:13:01.000000', NULL, 1),
