(579170, 59015, 15982, '<td valign="top">Nice Picture! Incredible detail. I wish the large ''blob'' in the top left wasn''t there. But still one of my favorites in the challenge - 10</td>', 'Nice Picture! Incredible detail. I wish the large ''blob'' in the top left wasn''t there. But still one of my favorites in the challenge - 10', '2004-02-13 11:09:19.000000', NULL, 1),
(579172, 59051, 15982, '<td valign="top">Great shot!!! I hope to see this at the top! 10</td>', 'Great shot!!! I hope to see this at the top! 10', '2004-02-13 11:09:50.000000', NULL, 1),
(579173, 59204, 15982, '<td valign="top">I love these. One of my favorite trees! Really nice detail! 10</td>', 'I love these. One of my favorite trees! Really nice detail! 10', '2004-02-13 11:10:37.000000', NULL, 1),
(579175, 59247, 15982, '<td valign="top">This is a wonderful shot. Something about it distracts me a little bit though. Maybe it is just too tight of a crop - not sure. But still in my top 10! 9</td>', 'This is a wonderful shot. Something about it distracts me a little bit though. Maybe it is just too tight of a crop - not sure. But still in my top 10! 9', '2004-02-13 11:11:41.000000', NULL, 1),
(579177, 59030, 15982, '<td valign="top">Cool picture! For some reason like I still want something more in it. Can''t put my finger on what, but I still really like the picture. Good luck!! 9</td>', 'Cool picture! For some reason like I still want something more in it. Can''t put my finger on what, but I still really like the picture. Good luck!! 9', '2004-02-13 11:13:05.000000', NULL, 1),
(579179, 59183, 15982, '<td valign="top">Great idea. Is the subject actually ''wavey'' or is it just an illusion from the text? Nice shot! Good luck!!</td>', 'Great idea. Is the subject actually ''wavey'' or is it just an illusion from the text? Nice shot! Good luck!!', '2004-02-13 11:14:47.000000', NULL, 1),
(579181, 59223, 15982, '<td valign="top">This would have been so much better without the light from the flash (in my opinion). Maybe could have used a pinlight or flashlight of some sort to illumintate the white a little better. I just have a thing against flashes.</td>', 'This would have been so much better without the light from the flash (in my opinion). Maybe could have used a pinlight or flashlight of some sort to illumintate the white a little better. I just have a thing against flashes.', '2004-02-13 11:16:50.000000', NULL, 1),
(579182, 58847, 15982, '<td valign="top">I see absolutely no shallow depth of field here. The entire picture is in focus. I think it could also be a little brighter. And if the dog is your main subject, then he could have used more detail on the fir. But I do not see this picture fitting this challenge in any way.</td>', 'I see absolutely no shallow depth of field here. The entire picture is in focus. I think it could also be a little brighter. And if the dog is your main subject, then he could have used more detail on the fir. But I do not see this picture fitting this challenge in any way.', '2004-02-13 11:19:00.000000', NULL, 1),
(579183, 58899, 15982, '<td valign="top">Beautiful picture, but I see absolutely nothing to do with SHALLOW DOF. Everything looks like a soft focus to me. I think the border could have been a little more subtle as well. But I see no way that this picture fits the challenge.</td>', 'Beautiful picture, but I see absolutely nothing to do with SHALLOW DOF. Everything looks like a soft focus to me. I think the border could have been a little more subtle as well. But I see no way that this picture fits the challenge.', '2004-02-13 11:20:50.000000', NULL, 1),
(579185, 59116, 15982, '<td valign="top">Where is the shallow DOF? The entire picture is in focus. Could have used a better light source to add interest, and the background is distracting. I see no way this picture conforms to the challenge.</td>', 'Where is the shallow DOF? The entire picture is in focus. Could have used a better light source to add interest, and the background is distracting. I see no way this picture conforms to the challenge.', '2004-02-13 11:23:40.000000', NULL, 1),
(579186, 59309, 15982, '<td valign="top">I really cannot justify how your picture fits the challenge. The arm is in focus from top to bottom. I can''t really find much interest here either. Nothing holds my eye. I think if the fingers were the only thing in focus and there was a little more light accentuating the hand, it would like much better. Good luck</td>', 'I really cannot justify how your picture fits the challenge. The arm is in focus from top to bottom. I can''t really find much interest here either. Nothing holds my eye. I think if the fingers were the only thing in focus and there was a little more light accentuating the hand, it would like much better. Good luck', '2004-02-13 11:27:03.000000', NULL, 1),
(579239, 59217, 10705, '<td valign="top">cool shot ... framing really adds to this photo.  nice job.</td>', 'cool shot ... framing really adds to this photo.  nice job.', '2004-02-13 13:08:21.000000', NULL, 1),
(579240, 59089, 10705, '<td valign="top">beautiful ... soft focus really works here!</td>', 'beautiful ... soft focus really works here!', '2004-02-13 13:09:44.000000', NULL, 1),
(579241, 59249, 10705, '<td valign="top">very nice</td>', 'very nice', '2004-02-13 13:10:40.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(579246, 59253, 10705, '<td valign="top">GO WINGS!!!  (sorry, just had to say it).<br/></td>', 'GO WINGS!!!  (sorry, just had to say it).', '2004-02-13 13:23:17.000000', NULL, 1),
(579247, 58640, 10705, '<td valign="top">very creative!</td>', 'very creative!', '2004-02-13 13:24:09.000000', NULL, 1),
(579255, 58861, 5792, '<td valign="top">Nicely composed, good color and no hot spots.  Beautiful.</td>', 'Nicely composed, good color and no hot spots.  Beautiful.', '2004-02-13 13:42:40.000000', NULL, 1),
(579256, 59242, 5792, '<td valign="top">Nicely fits the challenge. Efficiently composed. The shallow DOF main subject (hand on strings) blends well with the out-of-focus background (it is surprising how many others don''t) Very nice image.</td>', 'Nicely fits the challenge. Efficiently composed. The shallow DOF main subject (hand on strings) blends well with the out-of-focus background (it is surprising how many others don''t) Very nice image.', '2004-02-13 13:48:52.000000', NULL, 1),
(579257, 59292, 5792, '<td valign="top">Nice color contrast with the reds in the soft focused background.</td>', 'Nice color contrast with the reds in the soft focused background.', '2004-02-13 13:49:42.000000', NULL, 1),
(579258, 59043, 5792, '<td valign="top">Nice browns. Good lighting. Good technical quality.</td>', 'Nice browns. Good lighting. Good technical quality.', '2004-02-13 13:50:43.000000', NULL, 1),
(579259, 58389, 5792, '<td valign="top">Having the central focus of this image as the first string fits this particular challenge very well.</td>', 'Having the central focus of this image as the first string fits this particular challenge very well.', '2004-02-13 13:52:16.000000', NULL, 1),
(579260, 59229, 5792, '<td valign="top">Nice composition. Good use of ROT</td>', 'Nice composition. Good use of ROT', '2004-02-13 13:53:02.000000', NULL, 1),
(579264, 58473, 4493, '<td valign="top">I love this shot. Great composition and nice details in the leaf. The little ice crystals are an added bonus. 10 -danny</td>', 'I love this shot. Great composition and nice details in the leaf. The little ice crystals are an added bonus. 10 -danny', '2004-02-13 14:09:11.000000', NULL, 1),
(579265, 58302, 5792, '<td valign="top">Though probably better suited for the soft-focus challenge this is an exceptional portraiture. NeatImage would be perfect for smoothing the skin and giving it a soft focus effect and is DPC legal even for basic rule challenges. Hope you use it with your portraits.</td>', 'Though probably better suited for the soft-focus challenge this is an exceptional portraiture. NeatImage would be perfect for smoothing the skin and giving it a soft focus effect and is DPC legal even for basic rule challenges. Hope you use it with your portraits.', '2004-02-13 14:09:49.000000', NULL, 1),
(579266, 58555, 4493, '<td valign="top">Excellent image. Nice details and composition. I like how the eye is lead down the zipper into the more shallow DOF. 10 -danny</td>', 'Excellent image. Nice details and composition. I like how the eye is lead down the zipper into the more shallow DOF. 10 -danny', '2004-02-13 14:09:52.000000', NULL, 1),
(579269, 59269, 5792, '<td valign="top">The hooks are the perfect selection for your main subject. Nice color connection of the lure to the reel.</td>', 'The hooks are the perfect selection for your main subject. Nice color connection of the lure to the reel.', '2004-02-13 14:11:34.000000', NULL, 1),
(579270, 58784, 4493, '<td valign="top">Some may say this technique is over used, but I like the fact that some are frowning and others are smiling. It''s a fun shot! 9 -danny</td>', 'Some may say this technique is over used, but I like the fact that some are frowning and others are smiling. It''s a fun shot! 9 -danny', '2004-02-13 14:11:39.000000', NULL, 1),
(579271, 59127, 4493, '<td valign="top">Who''d you screw to get this shot? ;-) Excellent detail on the tip. Nice tone and shadow usage on the backdrop. 9 -danny</td>', 'Who''d you screw to get this shot? ;-) Excellent detail on the tip. Nice tone and shadow usage on the backdrop. 9 -danny', '2004-02-13 14:12:29.000000', NULL, 1),
(579272, 59217, 5792, '<td valign="top">Inspired idea to have your main subject coming out of the picture like this. The effect is particularly good for this challenge.</td>', 'Inspired idea to have your main subject coming out of the picture like this. The effect is particularly good for this challenge.', '2004-02-13 14:13:21.000000', NULL, 1),
(579274, 59137, 5792, '<td valign="top">You have taken a very ordinary object to create an extrordinary image.</td>', 'You have taken a very ordinary object to create an extrordinary image.', '2004-02-13 14:15:32.000000', NULL, 1),
