(580328, 59310, 8953, '<td valign="top">Clever take on the challenge! wish for just a little tighter DOF. still right at the top! 9</td>', 'Clever take on the challenge! wish for just a little tighter DOF. still right at the top! 9', '2004-02-15 02:08:05.000000', NULL, 1),
(580329, 59211, 8953, '<td valign="top">an attempt at shallow DOF created a wonderful soft focus image. Lovely Model. 9</td>', 'an attempt at shallow DOF created a wonderful soft focus image. Lovely Model. 9', '2004-02-15 02:09:41.000000', NULL, 1),
(580330, 59301, 8953, '<td valign="top">Great DOF....Not to fond of the colors though:(  7</td>', 'Great DOF....Not to fond of the colors though:(  7', '2004-02-15 02:11:09.000000', NULL, 1),
