(580489, 59011, 8953, '<td valign="top">You may have had others comment...would like to have seen the keys in focus. nice colors and DOF just the same.</td>', 'You may have had others comment...would like to have seen the keys in focus. nice colors and DOF just the same.', '2004-02-15 11:53:53.000000', NULL, 1),
(580490, 58672, 10818, '<td valign="top">That is an amazing shot......wall worthy for sure.  10</td>', 'That is an amazing shot......wall worthy for sure.  10', '2004-02-15 11:54:35.000000', NULL, 1),
(580491, 59127, 5391, '<td valign="top">Excellent shot - great composition and tonal range.  I sort of wish that the corkscrew came to a very sharp point that was highlighted by the depth of field - it appears to be a bit blunt, but overall very creative composition and perfect exposure.</td>', 'Excellent shot - great composition and tonal range.  I sort of wish that the corkscrew came to a very sharp point that was highlighted by the depth of field - it appears to be a bit blunt, but overall very creative composition and perfect exposure.', '2004-02-15 11:57:03.000000', NULL, 1),
(580493, 59282, 5391, '<td valign="top">You''ve definitely used depth of field very well to draw attention to the front orange slice.  The whites on the orange are just a tiny bit overexposed, so the viewer misses seeing detail in the main subject, which is a bit of a distraction.</td>', 'You''ve definitely used depth of field very well to draw attention to the front orange slice.  The whites on the orange are just a tiny bit overexposed, so the viewer misses seeing detail in the main subject, which is a bit of a distraction.', '2004-02-15 11:59:52.000000', NULL, 1),
(580495, 59038, 5391, '<td valign="top">Very nice - I love the creative composition with the pages sort of creating a checkmark against the black background, juxtaposed with your use of shallow depth of field to bring out the main subject.  8</td>', 'Very nice - I love the creative composition with the pages sort of creating a checkmark against the black background, juxtaposed with your use of shallow depth of field to bring out the main subject.  8', '2004-02-15 12:05:28.000000', NULL, 1),
