(581868, 59157, 6661, '<td valign="top">A beautiful image, beautifully captured. A coming together of vision and skill. Well done.</td>', 'A beautiful image, beautifully captured. A coming together of vision and skill. Well done.', '2004-02-16 12:41:08.000000', NULL, 0),
(581892, 58784, 4007, '<td valign="top">Having not voted in this challegne, when I saw this on the front page and recognized the droplet technique I admit that I cringed and said to myself "how the hell did another unoriginal copycat technique win another ribbon?"  Then I looked at it up close, and saw the frowning/smiling face effect from the inversion, and I smiled really big.  You earned this one by adding your creativity to a stale technique and pushing it to the next level.  I respect that.  Congratulations.</td>', 'Having not voted in this challegne, when I saw this on the front page and recognized the droplet technique I admit that I cringed and said to myself "how the hell did another unoriginal copycat technique win another ribbon?"  Then I looked at it up close, and saw the frowning/smiling face effect from the inversion, and I smiled really big.  You earned this one by adding your creativity to a stale technique and pushing it to the next level.  I respect that.  Congratulations.', '2004-02-16 13:07:28.000000', NULL, 0),
(581893, 58473, 11793, '<td valign="top">well done, one of three tens i gave this time.<br/> <br/>3rd place was one of the other 10''s...<br/> <br/>keep it up</td>', 'well done, one of three tens i gave this time. 3rd place was one of the other 10''s... keep it up', '2004-02-16 13:08:44.000000', NULL, 0),
